// ─── Configuración ────────────────────────────────────────────────────────
// LinkedIn solo expone analíticas de PÁGINAS DE EMPRESA, no de perfiles
// personales, y a través de la Community Management API, que exige aprobación
// en el Partner Program de LinkedIn.
//
// ORG_ID es el identificador numérico de tu página:
//   https://www.linkedin.com/company/<nombre>/  →  Admin → Page info
const AJUSTES = {
  ORG_ID: 'PON_AQUI_TU_ORG_ID',
  // Versión de la API en formato AAAAMM. La cabecera es obligatoria.
  LINKEDIN_VERSION: '202604',
  API_HOST: 'https://api.linkedin.com',
};

const env = (() => { try { return $env ?? {}; } catch { return {}; } })();
const ORG_ID = env.LINKEDIN_ORG_ID || AJUSTES.ORG_ID;
const VERSION = env.LINKEDIN_VERSION || AJUSTES.LINKEDIN_VERSION;
const HOST = env.LINKEDIN_API_HOST || AJUSTES.API_HOST;

if (ORG_ID === 'PON_AQUI_TU_ORG_ID') {
  throw new Error('Falta ORG_ID: rellénalo en el nodo Configuración o define LINKEDIN_ORG_ID.');
}

const ORG_URN = `urn:li:organization:${ORG_ID}`;


const COUNT = Number($input.first().json.query?.count ?? 10);

return [{ json: { orgId: ORG_ID, orgUrn: ORG_URN, version: VERSION, host: HOST, count: COUNT } }];

// LinkedIn no devuelve la URL de la imagen en el post: devuelve un URN que hay
// que resolver aparte. Aquí se recogen todos para pedirlos de una vez.
const posts = $('Publicaciones').first().json ?? {};

function urnOf(p) {
  const c = p.content ?? {};
  return c.media?.id
      ?? c.multiImage?.images?.[0]?.id
      ?? c.article?.thumbnail
      ?? null;
}

const urns = (posts.elements ?? []).map(urnOf).filter(Boolean);
const list = (arr) => 'List(' + arr.map(encodeURIComponent).join(',') + ')';

return [{ json: {
  ...$('Configuración').first().json,
  imageIds: urns.filter((u) => u.startsWith('urn:li:image:')),
  videoIds: urns.filter((u) => u.startsWith('urn:li:video:')),
  imageList: list(urns.filter((u) => u.startsWith('urn:li:image:'))),
  videoList: list(urns.filter((u) => u.startsWith('urn:li:video:'))),
} }];

// Une publicaciones, estadísticas y media en la forma que espera el panel.
const posts = $('Publicaciones').first().json ?? {};
const stats = $('Estadísticas por publicación').first().json ?? {};
const images = $('Imágenes').first().json ?? {};
const videos = $('Vídeos').first().json ?? {};

if (posts.message) return [{ json: { source: 'linkedin', error: posts.message, posts: [] } }];

const byUrn = {};
for (const el of stats.elements ?? []) {
  const urn = el.share ?? el.ugcPost ?? el.organizationalEntity;
  if (urn) byUrn[urn] = el.totalShareStatistics ?? el;
}

// El batch de Restli responde { results: { <urn>: {...} } }.
const media = { ...(images.results ?? {}), ...(videos.results ?? {}) };

function urnOf(p) {
  const c = p.content ?? {};
  return c.media?.id ?? c.multiImage?.images?.[0]?.id ?? c.article?.thumbnail ?? null;
}

function kindOf(p) {
  const c = p.content ?? {};
  if (c.multiImage) return 'carousel';
  if (c.article) return 'article';
  const urn = urnOf(p) ?? '';
  if (urn.startsWith('urn:li:video:')) return 'video';
  if (urn.startsWith('urn:li:image:')) return 'image';
  return 'text';
}

const fmt = (n) => (typeof n !== 'number' ? null : n >= 1e3 ? (n / 1e3).toFixed(1) + 'K' : String(n));

const rows = (posts.elements ?? []).map((p) => {
  const t = byUrn[p.id] ?? {};
  const urn = urnOf(p);
  const asset = urn ? media[urn] : null;
  const text = p.commentary
    ?? p.specificContent?.['com.linkedin.ugc.ShareContent']?.shareCommentary?.text
    ?? '';

  return {
    id: p.id,
    title: text.split('\n')[0].slice(0, 90) || 'Sin texto',
    excerpt: text.slice(0, 220),
    kind: kindOf(p),
    // Las URL de descarga de LinkedIn caducan; sirven para pintar ahora.
    image: asset?.downloadUrl ?? asset?.thumbnail ?? null,
    permalink: `https://www.linkedin.com/feed/update/${p.id}/`,
    publishedAt: p.publishedAt ?? p.createdAt ?? null,
    impressions: fmt(t.impressionCount),
    clicks: fmt(t.clickCount),
    likes: fmt(t.likeCount),
    comments: fmt(t.commentCount),
    shares: fmt(t.shareCount),
    engagement: typeof t.impressionCount === 'number' && t.impressionCount > 0
      ? Math.round(((t.likeCount ?? 0) + (t.commentCount ?? 0) + (t.shareCount ?? 0)) / t.impressionCount * 1000) / 10
      : null,
  };
});

const errors = [stats.message, images.message, videos.message].filter(Boolean);

return [{ json: { source: 'linkedin', errors, posts: rows } }];
